So I found a solution that worked for me, though I am not able to use the \ja in the url route, but instead use laravel's Session facade and update the locale in vue on the fly using createApp

npm install laravel-vue-i18n
publish the lang files: php artisan lang:publish
copy the en directory and change to your desired new locale (mine was ja)
optional (create a post.php or any other php file inside the directory)

app
  lang
    en
      auth.php
      pagination.php
      password.php
      post.php
      validation.php
    ja
      auth.php
      pagination.php
      password.php
      post.php
      validation.php


Add i18nVue from laravel-vue-i18n in app.ts file

File app.ts
// Format may be different for app.js (remove ':string') inside async
import { createApp, h, DefineComponent } from "vue";
import { createInertiaApp } from "@inertiajs/vue3";
import { i18nVue } from "laravel-vue-i18n";

createInertiaApp({
    ...
    setup({ el, App, props, plugin }) {
        createApp({ render: () => h(App, props) })
            ...
            .use(i18nVue, {
                fallbackLang: "en",
                resolve: async (lang: string) => {
                    const langs: any = import.meta.glob("../../lang/*.json");
                    return await langs[`../../lang/${lang}.json`]();
                },
            })
            ...
    },
});


add i18n in vite.config.js

vite.config.js
import i18n from "laravel-vue-i18n/vite";

export default defineConfig({
    plugins: [
        ...
        i18n(),
    ],
});


add lang/php_*.json in .gitignore
add a Route::group in your web.php. Also include the controller@method to update the locale.

File web.php
Route::post('/locale', [SetLocaleController::class, 'locale'])->name('locale');

Route::middleware(['setLocale'])->group(function () {
  Route::resource('posts', PostController::class);
  Route::resource('comments', CommentController::class);
});


create new middleware php artisan make:middleware SetLocaleMiddleware

File SetLocaleMiddleware.php
class SetLocaleMiddleware
{
    public function handle($request, Closure $next)
    {
        // get locale from session or get default value 'en'
        $locale = Session::get('locale', 'en');
        App::setLocale($locale);
        return $next($request);
    }
}


create new controller php artisan make:controller SetLocaleController

File SetLocaleController.php
class SetLocaleController extends Controller
{
    public function locale(Request $request)
    {
        // set locale to session
        Session::put('locale', $request->get('locale'));
        $data = ['locale' => $request->get('locale')];
        return response()->json($data);
    }
}


Update HandleInertiaRequests to return locale as props

File HandleInertiaRequests.php
class HandleInertiaRequests extends Middleware
{
    ...
    public function share(Request $request): array
    {
        return [
            ...parent::share($request),
            ...
            'locale' => Session::get('locale', 'en'),
            ...
        ];
    }
}


In your VueJS File, there are multiple ways to toggle locale select, radio, etc. Use what you want and maybe use below how to switch the locale:

import { createApp } from "vue";
import { i18nVue } from "laravel-vue-i18n";
import axios from "axios";

const app = createApp({});

// the method to update the locale. remote ':string` if in not using typescript.
const toggleLocale = async (locale: string) => {
    await axios
        .post(route("locale"), { locale: locale })
        .then((response) => {
            app.use(i18nVue, {
                lang: response.data.props.locale,
            });
        })
        .catch((error) => {
            console.log(error);
        });
};

Bonus, if you are experiencing error 419 (missing csrf token), do the following in your axios (preferably in app.ts/js)
import axios from "axios";
axios.defaults.withCredentials = true;
axios.defaults.withXSRFToken = true;

